	public void EmptyRejectionRetainsAllPinnedNativeRetriesCapturesAndOffsets( string hex, int mode, int empty, int policy, string protocols ) {
		var source = Convert.FromHexString( hex );
		var cases = protocols.Split( ';' ).Select( Protocol.Parse ).ToArray();
		var reference = Reference( source, mode, policy );
		// Check the complete native batch before a missing managed option can stop it.
		foreach ( var item in cases ) { AssertNative( reference, item.Subject, item.Offset, empty, item.Spans, item.Mark ); }
		var compiled = Compile( source, Options( mode, empty, policy ) );
		foreach ( var item in cases ) {
			Compare( reference, item.Subject, item.Offset, empty, compiled.Match( item.Subject, item.Offset ), $"{hex}/{mode}/{empty}/{policy}/{Convert.ToHexString( item.Subject )}/{item.Offset}" );
		}
	}

