	public void CallerMatchPoliciesDoNotAlterCompileErrorsOrSourceOffsets( string hex, int mode, int empty, int nativeCode, int nativeOffset, string code, int offset ) {
		var source = Convert.FromHexString( hex );
		var native = Assert.Throws<PcrePatternException>( () => Reference( source, mode ) );
		Assert.Equal( nativeCode, (int)native.ErrorCode );
		Assert.EndsWith( $" at offset {nativeOffset}.", native.Message );
		var actual = PcreByteCompiler.Compile( source, Options( mode, empty ) );
		Assert.Null( actual.Pattern );
		Assert.Equal( Enum.Parse<PcreByteDiagnosticCode>( code ), actual.Diagnostic?.Code );
		Assert.Equal( offset, actual.Diagnostic?.ByteOffset );
	}

	[Theory]
	[InlineData( 1, 0 )]
	[InlineData( 2, 0 )]
	[InlineData( 3, 0 )]
	[InlineData( 1, 1 )]
	[InlineData( 2, 1 )]
	[InlineData( 3, 1 )]
	public void RejectedEmptyPathsRetryWithinSharedWorkLimitsAndCancellation( int empty, int mode ) {
		var source = "|A"u8.ToArray();
		var subject = "A"u8.ToArray();
		var reference = Reference( source, mode );
		AssertNative( reference, subject, 0, empty, "0:1", "" );
		var steps = new List<int>();
		var prefixSteps = new List<int>();
		var options = Options( mode, empty ) with { WorkObserver = steps.Add };
		Compare( reference, subject, 0, empty, Compile( source, options ).Match( subject ), "retry acceptance" );
		var prefix = Encoding.UTF8.GetBytes( String.Concat( Prefix( empty ), "|A" ) );
		Compare( reference, subject, 0, empty, Compile( prefix, Options( mode, 0 ) with { WorkObserver = prefixSteps.Add } ).Match( subject ), "source equivalent" );
		Assert.Equal( prefixSteps, steps );
		Assert.Equal( Enumerable.Range( 1, steps.Count ), steps );
		Compare( reference, subject, 0, empty, Compile( source, options with { MatchWorkLimit = steps.Count } ).Match( subject ), "exact budget" );
		var limited = Compile( source, options with { MatchWorkLimit = steps.Count - 1 } ).Match( subject );
		Assert.Null( limited.Match );
		Assert.Equal( PcreByteDiagnosticCode.MatchWorkLimitExceeded, limited.Diagnostic?.Code );
		using var cancellation = new CancellationTokenSource();
		var cancellable = Compile( source, options with { WorkObserver = count => { if ( count == 2 ) { cancellation.Cancel(); } } } );
		Assert.Throws<OperationCanceledException>( () => cancellable.Match( subject, cancellationToken: cancellation.Token ) );
	}

