	public void CompiledPolicyAndOwnedLabelsSurviveCallerMutation( int empty ) {
		var source = "(*MARK:N)(A*?)"u8.ToArray();
		var subject = "A"u8.ToArray();
		var reference = Reference( source, 0 );
		AssertNative( reference, subject, 0, empty, "0:1,0:1", "4E" );
		var options = Options( 0, empty );
