	public void FirstNonemptySuccessDoesNotAddPolicyWork( int empty ) {
		var source = "A"u8.ToArray();
		var ordinary = new List<int>();
		var selected = new List<int>();
		Assert.Equal( new PcreByteCapture( 0, 1 ), Compile( source, Options( 0, 0 ) with { WorkObserver = ordinary.Add } ).Match( source ).Match?.Captures[0] );
